ST.xhtml:p:
Rtring_ABS(CLK := g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisAbs);
IF Rtring_ABS.Q THEN
  g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisAbs := FALSE;
    nAxisState := 1;
	AbsMoveDone := FALSE;
    AxisMoveDone :=FALSE;
(*  IF nAxisState <> 0 AND nAxisState <> 20 AND NCAxisName.NCTOPLC.ACTVELO > g_dCheckAxisIsMovingSpeedSet THEN
    g_bAxisIsMoveAlarm := TRUE;
    nAxisState := 21;
  END_IF;*)
END_IF;
NCAxisAbs(
     AXIS :=NCAxisName^(*AXIS_REF*),
     OUTAXIS => NCAxisName^(*AXIS_REF*));
NCAxisStop( 
    AXIS :=NCAxisName^(*AXIS_REF*),
     OUTAXIS => NCAxisName^(*AXIS_REF*));
CASE nAxisState OF
  0:
    nAxisState := 0;
  1:
    NCAxisAbs.Execute := TRUE;
    NCAxisAbs.Velocity := TargetVel;
    IF g_bSetAuxiliaryAxisSpeed THEN
      NCAxisAbs.Velocity := g_nAuxiliaryAxisSpeed;
      g_bSetAuxiliaryAxisSpeed := FALSE;
    END_IF;
    NCAxisAbs.Position := TargetPos;
    IF NCAxisAbs.Done THEN
      NCAxisAbs.Execute := FALSE;
      AbsMoveDone := TRUE;
      AxisMoveDone :=TRUE;
      nAxisState := 0;
    END_IF;    
    IF g_bPlcPauseBuffer THEN      
      NCAxisAbs.Execute := FALSE;
      g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisStop := TRUE;
      nAxisState := 20;
    END_IF;
    IF g_bPlcResetBuffer THEN
      nAxisState := 21;
    END_IF;
    IF NCAxisAbs.CommandAborted OR NCAxisAbs.Error THEN
      NCAxisAbs.Execute := FALSE;
      nAxisState := 0;
    END_IF;
  20:
     IF g_NCMoveData.NCAXISDATA[IndexNumber].AxisStopDone  THEN
      g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisStop := FALSE;
    END_IF;

    IF g_NCMoveData.NCAXISDATA[IndexNumber].AxisStopDone AND g_bPlcStartBuffer THEN
      nAxisState := 1;
    END_IF;

    IF g_bPlcResetBuffer THEN
      nAxisState := 0;
    END_IF;

    IF NCAxisStop.CommandAborted OR NCAxisStop.Error THEN
      g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisStop := FALSE;
      nAxisState := 0;
    END_IF;
  21:
    NCAxisAbs.Execute := FALSE;
    g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisStop := TRUE;
    IF g_NCMoveData.NCAXISDATA[IndexNumber].AxisStopDone THEN
      g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisStop := FALSE;
      nAxisState := 0;
      AbsMoveDone := TRUE;
      AxisMoveDone :=TRUE;
    END_IF;
    IF NCAxisStop.CommandAborted OR NCAxisStop.Error THEN
      g_NCMoveData.NCAXISCMD[IndexNumber].NCAxisStop := FALSE;
      nAxisState := 0;
    END_IF;
END_CASE;

ERRORID := NCAxisAbs.ERRORID;
